using LocalProductManager.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace LocalProductManager.Api.Services;

public static class DomesticProductSchema
{
    public static async Task UpgradeAsync(AppDbContext db)
    {
        var sql = db.Database.IsNpgsql()
            ? """
              CREATE TABLE IF NOT EXISTS domestic_product_infos (
                "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                "Sku" varchar(200) NOT NULL,
                "ProductCode" varchar(300), "ProductName" varchar(2000),
                "Material" varchar(500), "Specification" varchar(500),
                "CostRmb" numeric(14,4), "MinimumSalePriceUsd" numeric(14,4),
                "WarehouseInventory" integer, "SupplierName" varchar(500),
                "ChineseDeclarationName" varchar(1000), "EnglishDeclarationName" varchar(1000),
                "WeightGrams" numeric(14,4), "ImagePath" varchar(2000),
                "DetailsJson" text NOT NULL DEFAULT '{{}}', "SourceFileName" varchar(260),
                "ImportedAt" timestamp with time zone NOT NULL, "UpdatedAt" timestamp with time zone NOT NULL);
              CREATE UNIQUE INDEX IF NOT EXISTS "IX_domestic_product_infos_Sku" ON domestic_product_infos ("Sku");
              CREATE INDEX IF NOT EXISTS "IX_domestic_product_infos_ProductCode" ON domestic_product_infos ("ProductCode");
              CREATE INDEX IF NOT EXISTS "IX_domestic_product_infos_ProductName" ON domestic_product_infos ("ProductName");
              """
            : """
              CREATE TABLE IF NOT EXISTS domestic_product_infos (
                Id INTEGER NOT NULL CONSTRAINT PK_domestic_product_infos PRIMARY KEY AUTOINCREMENT,
                Sku TEXT NOT NULL, ProductCode TEXT NULL, ProductName TEXT NULL,
                Material TEXT NULL, Specification TEXT NULL, CostRmb TEXT NULL,
                MinimumSalePriceUsd TEXT NULL, WarehouseInventory INTEGER NULL,
                SupplierName TEXT NULL, ChineseDeclarationName TEXT NULL,
                EnglishDeclarationName TEXT NULL, WeightGrams TEXT NULL, ImagePath TEXT NULL,
                DetailsJson TEXT NOT NULL DEFAULT '{{}}', SourceFileName TEXT NULL,
                ImportedAt TEXT NOT NULL, UpdatedAt TEXT NOT NULL);
              CREATE UNIQUE INDEX IF NOT EXISTS IX_domestic_product_infos_Sku ON domestic_product_infos (Sku);
              CREATE INDEX IF NOT EXISTS IX_domestic_product_infos_ProductCode ON domestic_product_infos (ProductCode);
              CREATE INDEX IF NOT EXISTS IX_domestic_product_infos_ProductName ON domestic_product_infos (ProductName);
              """;
        await db.Database.ExecuteSqlRawAsync(sql);
    }
}
